%% For more information about options and configuration, please read
%% mdpusdoc.pdf or the general MathDesign documentation mddoc.pdf.

\NeedsTeXFormat{LaTeX2e}%

\ProvidesPackage{mdpus}%
[2013/08/29 v2.31 adobe utopia std + mdpus (Math Design Project)]

\@ifundefined{MD@default@family}{
    \PackageError{mdpus}%
    {Package mdpus cannot be loaded directly. Use mathdesign package.}
    {Use mathdesign package with option mdpus.}}
{\renewcommand{\rmdefault}{\MD@default@family}}


%% ----------------------------------------------------------------
%% External fonts can be scaled according to the following parameters (to
%% ensure correct lining of the glyphs)
%% ----------------------------------------------------------------

%% Bera (alias Bistream Vera)
\def\fvm@ratio{0.843}%
\def\fvs@ratio{0.843}%
\def\fve@ratio{0.843}%

%% Typewriter fonts
\def\pcr@ratio{1.082}%
\def\ucr@ratio{1.106}%

%% Sans Serif font
\def\phv@ratio{0.881}%
\def\uag@ratio{0.843}%
\def\uhv@ratio{0.880}%

%% Computer Modern fonts
\def\cmsy@ratio{0.952}%
\def\cmtt@ratio{1.071}%
\def\cmss@ratio{1.037}%

%% Euler fraktur
\def\euf@ratio{0.976}%

%% AMS blackboard bold
\def\msb@ratio{0.952}%

%% GFS Didot
\def\grd@ratio{0.983}%
%% GFS Bodoni
\def\grb@ratio{0.935}
%% Adobe Minion
\def\grm@ratio{1.055}

\input{mdfont.def}

\if@MD@sfscaled
  \input{mdsffont.def}
\fi

\if@MD@ttscaled
  \input{mdttfont.def}
\fi

%% ----------------------------------------------------------------
%% Script Math Alphabet
%% ----------------------------------------------------------------

\WarningIfLoaded{mdpus}{mathrsfs}%

\if@MD@cmcal
\DeclareSymbolFont{mdcal}{OMS}{xmdcmsy}{m}{n}%
\SetSymbolFont{mdcal}{bold}{OMS}{xmdcmsy}{b}{n}%
\else
\DeclareSymbolFont{mdcal}{OMS}{mdpus}{m}{n}%
\SetSymbolFont{mdcal}{bold}{OMS}{mdpus}{b}{n}%
\fi
\DeclareSymbolFontAlphabet{\mathcal}{mdcal}
\DeclareSymbolFont{mdscr}{OMS}{mdpus}{m}{n}%

\DeclareSymbolFontAlphabet{\mathscr}{mdscr}%
\SetSymbolFont{mdscr}{bold}{OMS}{mdpus}{b}{n}%

%% ----------------------------------------------------------------
%% Fraktur symbols support
%% ----------------------------------------------------------------

\DeclareMathAlphabet{\mathfrak}{U}{xmdeuf}{m}{n}%
\SetMathAlphabet{\mathfrak}{bold}{U}{xmdeuf}{b}{n}%
\DeclareRobustCommand{\frak}[1]{%
    {\@subst@obsolete{mdpus}\frak\mathfrak{#1}}}%

%% -------------------------------------------------------------------
%% Mathematical fonts definition
%% -------------------------------------------------------------------

% \DeclareMathVersion{mdpusnormal}
% \DeclareMathVersion{mdpusbold}

\SetSymbolFont{operators}   {normal}{OT1}{mdpus}{m}{n}%
\SetSymbolFont{letters}     {normal}{OML}{mdpus}{m}{it}%
\SetSymbolFont{symbols}     {normal}{OMS}{mdpus}{m}{n}%
\SetSymbolFont{largesymbols}{normal}{OMX}{mdpus}{m}{n}%

\SetSymbolFont{operators}   {bold}{OT1}{mdpus}{b}{n}%
\SetSymbolFont{letters}     {bold}{OML}{mdpus}{b}{it}%
\SetSymbolFont{symbols}     {bold}{OMS}{mdpus}{b}{n}%
\SetSymbolFont{largesymbols}{bold}{OMX}{mdpus}{b}{n}%

\SetMathAlphabet{\mathrm}{normal}{\encodingdefault}{\rmdefault}{m}{n}%
\SetMathAlphabet{\mathbf}{normal}{\encodingdefault}{\rmdefault}{b}{n}%
\SetMathAlphabet{\mathit}{normal}{\encodingdefault}{\rmdefault}{m}{it}%
\SetMathAlphabet{\mathsf}{normal}{\encodingdefault}{\sfdefault}{m}{n}%
\SetMathAlphabet{\mathtt}{normal}{\encodingdefault}{\ttdefault}{m}{n}%

\SetMathAlphabet{\mathrm}{bold} {\encodingdefault}{\rmdefault}{b}{n}%
\SetMathAlphabet{\mathbf}{bold} {\encodingdefault}{\rmdefault}{b}{n}%
\SetMathAlphabet{\mathit}{bold} {\encodingdefault}{\rmdefault}{b}{it}%
\SetMathAlphabet{\mathsf}{bold} {\encodingdefault}{\sfdefault}{b}{n}%
\SetMathAlphabet{\mathtt}{bold} {\encodingdefault}{\ttdefault}{b}{n}%

\DeclareSymbolFont{lettersupright}     {OML}{mdpus}{m}{n}
\SetSymbolFont{lettersupright}   {bold}{OML}{mdpus}{b}{n}%
\DeclareSymbolFontAlphabet{\mathrm}    {lettersupright}

% -------------------------------------------------------------------
% Greek alphabet

\def\MDgrfamily{letters}

\ifthenelse{\equal{\MD@greek@family}{letters}}
{}
